"""Real native notification API checks on a private bus; no desktop shell restart."""
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest

HARNESS = 'import Quickshell\nimport Quickshell.Io\nimport Quickshell.Services.Notifications\nimport QtQuick\nimport "."\nShellRoot {\n id: root\n property var reasons: []\n NotificationServer { actionsSupported: true; onNotification: n => { n.closed.connect(reason => root.reasons = root.reasons.concat([reason])); NotificationHistory.receive(n) } }\n IpcHandler {\n  target: "test"\n  function state(): string { return JSON.stringify({storage:NotificationHistory.storageAvailable, ready:NotificationHistory.storageReady, reasons: root.reasons, entries: NotificationHistory.entries, active: Object.keys(NotificationHistory.active).map(id => ({id:id, remaining:NotificationHistory.active[id].remaining, persistent:NotificationHistory.active[id].persistent}))}) }\n  function pause(id: string, value: bool): void { NotificationHistory.current(id).pause(value) }\n  function dismiss(id: string): void { NotificationHistory.dismiss(id) }\n  function clear(): void { NotificationHistory.clear() }\n  function invoke(id: string): void { NotificationHistory.invoke(id, "default") }\n }\n}\n'
CHECKER = 'import json, os, subprocess, time\nfrom pathlib import Path\nroot=Path(__file__).parent\ntest_env={k:v for k,v in dict(os.environ,QT_QPA_PLATFORM="offscreen",QT_QPA_PLATFORMTHEME="generic",QT_QUICK_CONTROLS_STYLE="Basic").items() if k not in ("WAYLAND_DISPLAY", "DISPLAY", "HYPRLAND_INSTANCE_SIGNATURE")}\np=subprocess.Popen(["qs","-p",str(root/"shell.qml")],env=test_env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)\ndef ipc(*args):\n return subprocess.check_output(["qs","-p",str(root/"shell.qml"),"ipc","call","test",*args],text=True,stderr=subprocess.STDOUT,timeout=5,env=test_env).strip()\ndef state(): return json.loads(ipc("state"))\ndef notify(timeout,replace=0,critical=False):\n args=["busctl","--user","call","org.freedesktop.Notifications","/org/freedesktop/Notifications","org.freedesktop.Notifications","Notify","susssasa{sv}i","Fixture",str(replace),"","Summary","Body","2","default","Open",str(int(critical))]\n if critical: args += ["urgency","y","2"]\n args += [str(timeout)]\n return subprocess.check_output(args,text=True).strip().split()[-1]\ntry:\n for i in range(50):\n  try: state(); break\n  except subprocess.CalledProcessError: time.sleep(.1)\n else: raise AssertionError("startup failed")\n ident=notify(1200)\n time.sleep(.3); a=state()["active"][0]["remaining"]\n ipc("pause",ident,"true"); time.sleep(.5); b=state()["active"][0]["remaining"]\n assert abs(a-b)<150,(a,b)\n ipc("pause",ident,"false"); time.sleep(.3); assert state()["active"][0]["remaining"]<b-150\n time.sleep(1); assert not state()["active"]; assert len(state()["entries"])==1; assert state()["reasons"][-1]==1\n ident=notify(0); time.sleep(.2); assert state()["active"][0]["persistent"]\n notify(900,replace=int(ident)); time.sleep(.1); assert len(state()["entries"])==2\n assert not state()["active"][0]["persistent"]\n ipc("dismiss",ident); time.sleep(.1); assert not state()["active"]; assert state()["reasons"][-1]==2\n ident=notify(200,critical=True); time.sleep(.4); assert state()["active"][0]["persistent"]\n ipc("invoke",ident); time.sleep(.1); assert not state()["active"]\n ident=notify(0)\n subprocess.check_call(["busctl","--user","call","org.freedesktop.Notifications","/org/freedesktop/Notifications","org.freedesktop.Notifications","CloseNotification","u",ident])\n time.sleep(.1); assert state()["reasons"][-1]==3\n time.sleep(.4)\n assert state()["storage"] and state()["ready"]\n archive=Path(os.environ["XDG_STATE_HOME"])/"quattro/notifications/history.json"\n assert archive.exists() and archive.stat().st_mode & 0o777 == 0o600\n assert len(json.loads(archive.read_text()))==4\n p.terminate(); p.communicate(timeout=5)\n p=subprocess.Popen(["qs","-p",str(root/"shell.qml")],env=test_env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)\n for i in range(60):\n  try:\n   restored=state()\n   if restored["ready"]: break\n  except subprocess.CalledProcessError: pass\n  time.sleep(.05)\n else: raise AssertionError("archive did not load")\n assert restored["storage"] and len(restored["entries"])==4 and not restored["active"]\n ipc("clear"); time.sleep(.4)\n assert not state()["entries"] and not json.loads(archive.read_text())\n print("PASS: native receive, duration, hover pause/resume, expiration, replacement, persistent/critical, action")\nfinally:\n p.terminate()\n try: output=p.communicate(timeout=5)[0].decode()\n except subprocess.TimeoutExpired: p.kill(); output=p.communicate()[0].decode()\n print(output)\n'
BUS_CONFIG = '<busconfig><type>session</type><listen>unix:tmpdir=/tmp</listen><policy context="default"><allow send_destination="*"/><allow receive_sender="*"/><allow own="*"/></policy></busconfig>'

@unittest.skipUnless(all(shutil.which(c) for c in ("qs", "busctl", "dbus-run-session")), "Requires Quickshell and D-Bus")
class NotificationRuntimeTests(unittest.TestCase):
    def test_native_lifetime_history_replacement_actions(self):
        with tempfile.TemporaryDirectory(prefix="quattro-notifications-") as folder:
            root = Path(folder)
            source = Path(__file__).resolve().parents[1] / "src/quickshell/services/NotificationHistory.qml"
            shutil.copyfile(source, root / "NotificationHistory.qml")
            helper = root / ".local/bin/quattro-notification-store"
            helper.parent.mkdir(parents=True)
            shutil.copyfile(Path(__file__).resolve().parents[1] / "src/quattro-notification-store", helper)
            (root / "qmldir").write_text("singleton NotificationHistory 1.0 NotificationHistory.qml\n")
            (root / "shell.qml").write_text(HARNESS)
            (root / "check.py").write_text(CHECKER)
            (root / "bus.conf").write_text(BUS_CONFIG)
            result = subprocess.run(["dbus-run-session", "--config-file=" + str(root / "bus.conf"), "python", str(root / "check.py")], capture_output=True, text=True, timeout=40,
                env=dict(os.environ, HOME=str(root), XDG_STATE_HOME=str(root / "state")))
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            self.assertIn("PASS:", result.stdout)
